const sceneGeometry=new WeakMap();
/** One immutable geometry per scene. UV.x selects a semantic palette texel. */
export function createStandingTechnician(B,scene,{name='standing-technician',material=null}={}) {
 let geometry=sceneGeometry.get(scene);
 if(!geometry||geometry.isDisposed()) {
  const vd=new B.VertexData();vd.positions=TECHNICIAN_DATA.positions;vd.normals=TECHNICIAN_DATA.normals;vd.indices=TECHNICIAN_DATA.indices;
  vd.uvs=TECHNICIAN_DATA.triangleRoles.flatMap(role=>Array.from({length:3},()=>[(role+.5)/TECHNICIAN_METADATA.roles.length,.5]).flat());
  geometry=new B.Geometry('shared-standing-technician-geometry',scene,vd,false);sceneGeometry.set(scene,geometry);
 }
 const mesh=new B.Mesh(name,scene);geometry.applyToMesh(mesh);mesh.material=material;mesh.isPickable=false;
 mesh.metadata={asset:TECHNICIAN_METADATA.name,bounds:TECHNICIAN_METADATA.bounds,semanticRoles:TECHNICIAN_METADATA.roles};return mesh;
}
